custom_qss:
/* PHOSPHOR — CRT terminal. P1 phosphor green on near-black, monospace,
   hard-stop gradient banding = scanlines. No boxes, no translucency. */

* {
    border: none;
    background-color: transparent !important;
    color: #7dffab !important;
    font-family: "Consolas", "Courier New", monospace;
}

QAbstractScrollArea, QFrame, QStackedWidget, QScrollArea, QTabWidget, QWidget {
    background: transparent !important;
    border: none;
}

/* window: faint green cast, brighter at top like a CRT */
QMainWindow {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #04140a, stop:0.5 #020a05, stop:1 #010604) !important;
}
QDialog {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #04140a, stop:1 #010604) !important;
}

QMenuBar { background: transparent !important; }
QMenuBar::item {
    padding: 5px 12px;
    border-radius: 2px;
    background: transparent !important;
    color: #4fbf7a !important;
}
QMenuBar::item:selected {
    background: #0d3d1e !important;
    color: #b6ffcd !important;
}
QMenuBar::item:disabled { color: #245c38 !important; }

QMenu {
    background: #020a05 !important;
    border: 1px solid #1f7a45;
    border-radius: 2px;
    padding: 4px;
}
QMenu::item {
    padding: 5px 22px 5px 12px;
    border-radius: 0px;
    background: transparent !important;
    color: #7dffab !important;
}
QMenu::item:selected {
    background: #144d2b !important;
    color: #c9ffe0 !important;
}
QMenu::item:disabled { color: #245c38 !important; }
QMenu::separator { height: 1px; background: #14522e; margin: 4px 6px; }
QMenu::icon { padding-left: 4px; }

QToolBar {
    background: transparent !important;
    spacing: 2px;
    padding: 3px;
}
QToolBar::separator { background: #14522e; width: 1px; margin: 5px 3px; }
QToolBar QToolButton {
    background: transparent !important;
    padding: 4px 7px;
    border-radius: 2px;
    color: #4fbf7a !important;
}
QToolBar QToolButton:hover {
    background: #0d3d1e !important;
    color: #b6ffcd !important;
}
QToolBar QToolButton:checked, QToolBar QToolButton:pressed {
    background: #144d2b !important;
    color: #c9ffe0 !important;
}
QToolBar QToolButton:disabled { color: #245c38 !important; }

QToolButton {
    background: transparent !important;
    padding: 4px 7px;
    border-radius: 2px;
    color: #4fbf7a !important;
}
QToolButton:hover { background: #0d3d1e !important; color: #b6ffcd !important; }
QToolButton:checked, QToolButton:pressed {
    background: #144d2b !important;
    color: #c9ffe0 !important;
}
QToolButton:disabled { color: #245c38 !important; }

/* buttons: terminal keys — flat, hairline, no radius drama */
QPushButton {
    background: #05160c !important;
    border: 1px solid #1a6b3e;
    border-radius: 2px;
    padding: 5px 16px;
    color: #7dffab !important;
}
QPushButton:hover {
    background: #0d3d1e !important;
    border: 1px solid #35c46e;
    color: #c9ffe0 !important;
}
QPushButton:pressed {
    background: #144d2b !important;
    color: #ffffff !important;
}
QPushButton:checked {
    background: #144d2b !important;
    border: 1px solid #35c46e;
    color: #ffffff !important;
}
QPushButton:disabled {
    background: #020a05 !important;
    border: 1px solid #103a22;
    color: #245c38 !important;
}

QLineEdit, QSpinBox, QDoubleSpinBox, QTextEdit, QPlainTextEdit {
    background: #010604 !important;
    border: 1px solid #1a6b3e;
    border-radius: 0px;
    padding: 4px 7px;
    color: #b6ffcd !important;
    selection-background-color: #144d2b;
    selection-color: #ffffff;
}
QLineEdit:focus, QSpinBox:focus, QDoubleSpinBox:focus, QTextEdit:focus, QPlainTextEdit:focus {
    border: 1px solid #35c46e;
    color: #ffffff !important;
}
QLineEdit:disabled, QSpinBox:disabled, QDoubleSpinBox:disabled,
QTextEdit:disabled, QPlainTextEdit:disabled { color: #245c38 !important; }
QSpinBox::up-button, QSpinBox::down-button,
QDoubleSpinBox::up-button, QDoubleSpinBox::down-button {
    background: transparent !important;
    border: none;
    width: 15px;
}

QComboBox {
    background: #05160c !important;
    border: 1px solid #1a6b3e;
    border-radius: 0px;
    padding: 4px 7px;
    color: #7dffab !important;
}
QComboBox:hover { border: 1px solid #35c46e; }
QComboBox:focus { border: 1px solid #35c46e; }
QComboBox::drop-down { border: none; background: transparent !important; width: 16px; }
QComboBox QAbstractItemView {
    background: #020a05 !important;
    border: 1px solid #35c46e;
    border-radius: 0px;
    padding: 3px;
    selection-background-color: #144d2b;
}
QComboBox:disabled { color: #245c38 !important; }

/* checkboxes: square terminal cells */
QCheckBox, QRadioButton {
    color: #7dffab !important;
    background: transparent !important;
    padding: 2px;
}
QCheckBox::indicator, QRadioButton::indicator {
    width: 14px; height: 14px;
    background: #010604 !important;
    border: 1px solid #1a6b3e;
    border-radius: 0px;
}
QRadioButton::indicator { border-radius: 7px; }
QCheckBox::indicator:hover, QRadioButton::indicator:hover { border: 1px solid #35c46e; }
QCheckBox::indicator:checked, QRadioButton::indicator:checked {
    background: #35c46e !important;
}
QCheckBox:disabled, QRadioButton:disabled { color: #245c38 !important; }

/* tabs: blocky, no radius, active = inverted */
QTabBar { background: transparent !important; }
QTabBar::tab {
    background: transparent !important;
    color: #4fbf7a !important;
    padding: 6px 16px;
    margin: 0 1px;
    border-radius: 0px;
}
QTabBar::tab:hover { color: #b6ffcd !important; background: #05160c !important; }
QTabBar::tab:selected {
    background: #144d2b !important;
    color: #ffffff !important;
}
QTabBar::tab:disabled { color: #245c38 !important; }
QTabBar::close-button { background: transparent !important; border: none; }
QTabBar::close-button:hover { background: #144d2b !important; }
QTabWidget::pane { border: 1px solid #103a22; background: transparent !important; }

/* docks: SCANLINE BANDING via hard-stop gradient — the signature move */
QDockWidget { background: transparent !important; border: none; }
QDockWidget::title {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #0a2f18, stop:0.5 #0a2f18, stop:0.5 #04160c,
        stop:1 #04160c) !important;
    border: none;
    border-bottom: 1px solid #1a6b3e;
    border-left: 3px solid #35c46e;
    padding: 6px 9px;
    color: #b6ffcd !important;
    font-weight: 600;
}
QDockWidget::close-button, QDockWidget::float-button {
    background: transparent !important; border: none; padding: 2px;
}
QDockWidget::close-button:hover, QDockWidget::float-button:hover {
    background: #144d2b !important;
}

QGroupBox {
    background: transparent !important;
    border: none;
    border-bottom: 1px solid #103a22;
    margin-top: 14px;
    padding-top: 6px;
    font-weight: 600;
    color: #7dffab !important;
}
QGroupBox::title {
    subcontrol-origin: margin;
    subcontrol-position: top left;
    padding: 0 6px;
    background: transparent !important;
    color: #35c46e !important;
}

QAbstractItemView {
    background: #010604 !important;
    border: 1px solid #103a22;
    border-radius: 0px;
    alternate-background-color: #04140a;
    selection-background-color: #144d2b;
    selection-color: #ffffff;
    outline: none;
}
QAbstractItemView::item { padding: 3px; }
QAbstractItemView::item:hover { background: #0a2415 !important; }
QAbstractItemView::item:selected {
    background: #144d2b !important;
    color: #ffffff !important;
    border-left: 3px solid #35c46e;
}
QAbstractItemView::item:selected:!active {
    background: #0a2f18 !important;
    border-left: 3px solid #14522e;
}
QTreeView::item, QTreeWidget::item, QTreeWidgetItem,
QTableView::item, QListView::item, QListWidget::item {
    background: transparent !important;
}

QHeaderView { background: transparent !important; border: none; }
QHeaderView::section {
    background: #04140a !important;
    border: none;
    border-bottom: 1px solid #1a6b3e;
    padding: 5px 7px;
    color: #4fbf7a !important;
    font-weight: 600;
}
QHeaderView::section:hover { color: #b6ffcd !important; }

/* scrollbars: thin, blocky, phosphor */
QScrollBar:vertical { background: #010604 !important; width: 12px; margin: 0; }
QScrollBar::handle:vertical {
    background: #144d2b !important;
    border: 1px solid #1a6b3e;
    border-radius: 0px;
    min-height: 26px;
}
QScrollBar::handle:vertical:hover { background: #35c46e !important; }
QScrollBar::add-line:vertical, QScrollBar::sub-line:vertical {
    height: 0; background: none; border: none;
}
QScrollBar::add-page:vertical, QScrollBar::sub-page:vertical {
    background: #010604 !important;
}
QScrollBar:horizontal { background: #010604 !important; height: 12px; margin: 0; }
QScrollBar::handle:horizontal {
    background: #144d2b !important;
    border: 1px solid #1a6b3e;
    border-radius: 0px;
    min-width: 26px;
}
QScrollBar::handle:horizontal:hover { background: #35c46e !important; }
QScrollBar::add-line:horizontal, QScrollBar::sub-line:horizontal {
    width: 0; background: none; border: none;
}
QScrollBar::add-page:horizontal, QScrollBar::sub-page:horizontal {
    background: #010604 !important;
}
QScrollBar::corner { background: #010604 !important; }

/* sliders: square phosphor fill */
QSlider::groove:horizontal {
    background: #010604 !important;
    border: 1px solid #103a22;
    height: 5px; border-radius: 0px;
}
QSlider::sub-page:horizontal {
    background: #35c46e !important;
    border-radius: 0px;
}
QSlider::add-page:horizontal {
    background: #010604 !important;
    border-radius: 0px;
}
QSlider::handle:horizontal {
    background: #b6ffcd !important;
    border: 1px solid #35c46e;
    width: 9px; margin: -4px 0; border-radius: 0px;
}
QSlider::handle:horizontal:hover { background: #ffffff !important; }
QSlider::groove:vertical {
    background: #010604 !important;
    border: 1px solid #103a22;
    width: 5px; border-radius: 0px;
}
QSlider::sub-page:vertical { background: #35c46e !important; border-radius: 0px; }
QSlider::add-page:vertical { background: #010604 !important; border-radius: 0px; }
QSlider::handle:vertical {
    background: #b6ffcd !important;
    border: 1px solid #35c46e;
    height: 9px; margin: 0 -4px; border-radius: 0px;
}
QSlider::handle:vertical:hover { background: #ffffff !important; }

/* progress: scanline banded fill */
QProgressBar {
    background: #010604 !important;
    border: 1px solid #1a6b3e;
    border-radius: 0px;
    text-align: center;
    color: #b6ffcd !important;
    min-height: 15px;
}
QProgressBar::chunk {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #35c46e, stop:0.5 #35c46e, stop:0.5 #1a8a45,
        stop:1 #1a8a45) !important;
}

/* statusbar: second scanline surface */
QStatusBar {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #0a2f18, stop:0.5 #0a2f18, stop:0.5 #04160c,
        stop:1 #04160c) !important;
    border: none;
    border-top: 1px solid #1a6b3e;
    color: #4fbf7a !important;
}
QStatusBar::item { background: transparent !important; }
QStatusBar QLabel { color: #4fbf7a !important; }

QToolTip {
    background: #020a05 !important;
    border: 1px solid #35c46e;
    border-radius: 0px;
    padding: 5px 8px;
    color: #b6ffcd !important;
}

QSplitter { background: transparent !important; border: none; }
QSplitter::handle { background: #0a2415 !important; }
QSplitter::handle:hover { background: #144d2b !important; }
